  }
  if (!/^\d+$/.test(decoded)) {
    throw new Error('Invalid cursor');
  }
  const offset = Number(decoded);
  if (!Number.isInteger(offset) || offset <= 0 || offset >= events.length) {
    throw new Error('Invalid cursor');
  }
  return offset;
}

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events in source order with optional cursor-based pagination',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: { type: 'string', description: 'Opaque pagination cursor from a previous response' },
          page_size: { type: 'integer', minimum: 1, maximum: 3, description: 'Events per page (1-3, default 2)' }
        },
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'events_list') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate no extra fields
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  let start = 0;

  if (args.cursor !== undefined) {
    if (typeof args.cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    start = decodeCursor(args.cursor);
  }

  let pageSize = DEFAULT_PAGE_SIZE;
  if (args.page_size !== undefined) {
    if (!Number.isInteger(args.page_size) || args.page_size < MIN_PAGE_SIZE || args.page_size > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer between 1 and 3');
    }
    pageSize = args.page_size;
